INSERT INTO public.projects (slug, title, description, long_description, tags, github_url, demo_url, image_url, images, featured)
VALUES
('decentrashare-blockchain', 'DecentraShare – Sistem File Sharing Berbasis Blockchain', 'Sistem file sharing berbasis web yang mengintegrasikan PostgreSQL, IPFS, dan blockchain Ethereum untuk pengelolaan file dan metadata terdesentralisasi.', 'Merancang dan mengembangkan sistem file sharing berbasis web yang mengintegrasikan database PostgreSQL, IPFS, dan blockchain Ethereum untuk pengelolaan file dan metadata. Mengembangkan backend REST API menggunakan Express.js, TypeScript, dan Prisma ORM serta mengimplementasikan smart contract menggunakan Solidity untuk pencatatan metadata file pada blockchain. Mengintegrasikan IPFS dan MetaMask untuk penyimpanan file terdesentralisasi serta autentikasi dan transaksi berbasis blockchain.', ARRAY['SvelteKit', 'Express.js', 'TypeScript', 'Prisma ORM', 'PostgreSQL', 'Solidity', 'Ethereum', 'IPFS', 'MetaMask'], 'https://github.com/dimasprayogox', '', 'https://images.unsplash.com/photo-1639762681485-074b7f938ba0?auto=format&fit=crop&w=800&q=80', ARRAY['https://images.unsplash.com/photo-1639762681485-074b7f938ba0?auto=format&fit=crop&w=800&q=80'], true),
('work-order-asset-management', 'Work Order – Sistem Manajemen Aset dan Work Order', 'Sistem CMMS berbasis web untuk pengelolaan dan proses maintenance aset perusahaan manufaktur dengan role-based access.', 'Mengembangkan sistem CMMS berbasis web untuk pengelolaan dan proses maintenance aset pada perusahaan manufaktur. Membangun fitur manajemen aset, work order, dan role-based access. Mengembangkan aplikasi secara end-to-end, mulai dari perancangan, implementasi, hingga pengujian dibawah pengawasan Project Manager PT. Marstech Global.', ARRAY['Next.js', 'Express.js', 'Knex', 'MySQL'], 'https://github.com/dimasprayogox', '', 'https://images.unsplash.com/photo-1581092160607-ee22621dd758?auto=format&fit=crop&w=800&q=80', ARRAY['https://images.unsplash.com/photo-1581092160607-ee22621dd758?auto=format&fit=crop&w=800&q=80'], true);
